def stufen_umstellen(apps, schema_editor):
    """Alte Zugriffsstufen übernehmen und Dateimetadaten vorhandener Dokumente nachtragen."""
    import mimetypes
    import os

    Dokument = apps.get_model("stammdaten", "Dokument")
    zuordnung = {"normal": "akte", "vertraulich": "verwaltung"}
    for d in Dokument.objects.all():
        d.zugriffsstufe = zuordnung.get(d.zugriffsstufe, d.zugriffsstufe)
        if d.datei and not d.originalname:
            d.originalname = os.path.basename(d.datei.name)[:200]
            d.inhaltstyp = mimetypes.guess_type(d.datei.name)[0] or "application/octet-stream"
            try:
                d.groesse = d.datei.size
            except OSError:
                d.groesse = 0
        d.save(update_fields=["zugriffsstufe", "originalname", "inhaltstyp", "groesse"])


